V38.logHTML=n=>{const L=V38.mem.log.slice(0,n);return L.length?`<ol class="v38-log">${L.map(l=>`<li><b>${esc(l.a)}</b> <span>${esc(l.d)}</span><small>${esc(V38.fmt(l.at))}</small></li>`).join("")}</ol>`:`<p class="mut">Henüz kayıtlı işlem yok.</p>`};
