OGRT.EXT.ilerleme=function(){return OGRT.vIler()+(OGRT.d.classes.length?`<section class="og-sec v38-rp"><h2>Kazanım takip raporu</h2><p class="small mut">Ünite bazında, senin işaretlemelerinden ve ders planlarından hesaplanır.</p>${OGRT.d.classes.map(x=>V38.rapor(x.g,x.py)).join("")}<div class="v38-acts"><button class="v38-b" onclick="V38.raporCSV()">${V38.svg("dl",18)} Raporu indir (CSV)</button></div></section>`:"")};
V38.raporRows=function(g,py){return OGRT.units(g,py).map(u=>{const L=OGRT.outs(u.id),c={bas:0,plan:0,isl:0,tek:0};L.forEach(o=>c[OGRT.st(o.id)]++);const pl=OGRT.d.plans.filter(p=>L.some(o=>o.id===p.oid)).length;return{u,t:L.length,c,pl}})};
V38.rapor=(g,py)=>{const R=V38.raporRows(g,py);return `<div class="v38-card"><h3>${g}. sınıf · ${esc(OGRT.pyName(py))}</h3><div class="og-tw"><table class="og-t v38-t"><thead><tr><th>Ünite</th><th>Kazanım</th><th>✓ İşlendi</th><th>◔ Planlandı</th><th>↻ Tekrar</th><th>○ Başlanmadı</th><th>Ders planı</th></tr></thead><tbody>${R.map(r=>`<tr><td>${r.u.order}. ${esc(r.u.title)}</td><td>${r.t}</td><td>${r.c.isl}</td><td>${r.c.plan}</td><td>${r.c.tek}</td><td>${r.c.bas}</td><td>${r.pl}</td></tr>`).join("")}</tbody></table></div></div>`};
V38.raporCSV=function(){const q=v=>`"${String(v).replace(/"/g,'""')}"`,rows=[["Sınıf","Program","Ünite","Kazanım","İşlendi","Planlandı","Tekrar","Başlanmadı","Ders planı"]];OGRT.d.classes.forEach(x=>V38.raporRows(x.g,x.py).forEach(r=>rows.push([x.g,x.py,r.u.order+". "+r.u.title,r.t,r.c.isl,r.c.plan,r.c.tek,r.c.bas,r.pl])));V38.download("kazanim-raporu-"+OGRT.today()+".csv","﻿"+rows.map(r=>r.map(q).join(";")).join("\n"),"text/csv");V38.logT("Rapor indirildi","CSV")};
