OGRT.EXT.notlar=function(){const s=V38.NS(),q=s.q.toLocaleLowerCase("tr-TR"),L=V38.mem.notlar.filter(n=>(!s.f||(s.f==="taslak"?n.taslak:!n.taslak))&&(!q||(n.title+" "+n.text).toLocaleLowerCase("tr-TR").includes(q))).sort((a,b)=>String(b.updated).localeCompare(String(a.updated)));
 const WN=[];Object.entries(OGRT.W.d.notes||{}).forEach(([k,arr])=>{const[g,py,sy,n]=k.split("|");(arr||[]).forEach(x=>WN.push({g,py,sy,n,x}))});
 const form=n=>`<form class="v38-nf og-form" onsubmit="return V38.notSave(event,'${n?n.id:""}')"><label>Başlık<input name="title" maxlength="140" value="${esc(n?n.title:"")}" required></label><label>Not<textarea name="text" rows="6" maxlength="20000" required>${esc(n?n.text:"")}</textarea></label><div class="og-fr"><label>Sınıf (isteğe bağlı)<select name="cls"><option value="">—</option>${OGRT.d.classes.map(c=>{const k=OGRT.ck(c.g,c.py);return `<option value="${k}" ${n&&n.cls===k?"selected":""}>${c.g}. sınıf ${c.py}</option>`}).join("")}</select></label><label class="v38-ck"><input type="checkbox" name="taslak" ${n&&n.taslak?"checked":""}> Taslak</label></div><div class="og-acts"><button class="p" type="submit">Kaydet</button><button type="button" onclick="V38.NS().ed='';OGRT.render()">Vazgeç</button>${n?`<button type="button" class="v38-danger" onclick="V38.notDel('${n.id}')">Sil</button>`:""}</div></form>`;
 return `<section class="og-sec"><h2>Notlar ve Taslaklar</h2>${V38.wait()}<div class="v38-fbar"><input type="search" placeholder="Notlarda ara" value="${esc(s.q)}" aria-label="Notlarda ara" onchange="V38.NS().q=this.value;OGRT.render()"><select aria-label="Not türü" onchange="V38.NS().f=this.value;OGRT.render()"><option value="">Tümü</option><option value="not" ${s.f==="not"?"selected":""}>Notlar</option><option value="taslak" ${s.f==="taslak"?"selected":""}>Taslaklar</option></select><button class="v38-b p" onclick="V38.NS().ed='new';OGRT.render()">+ Yeni not</button></div>
 ${s.ed==="new"?form(null):""}${L.length?`<ul class="v38-notes">${L.map(n=>s.ed===n.id?`<li>${form(n)}</li>`:`<li class="v38-card"><div class="v38-nh"><b>${esc(n.title)}</b>${n.taslak?`<i class="v38-tg">Taslak</i>`:""}${n.cls?`<i class="v38-tg">${esc(n.cls.replace("|",". sınıf "))}</i>`:""}<small>${esc(V38.fmt(n.updated))}</small></div><p class="v38-pre">${esc(n.text)}</p><button class="v38-b" onclick="V38.NS().ed='${n.id}';OGRT.render()">Düzenle</button></li>`).join("")}</ul>`:`<p class="v38-empty">${V38.mem.notlar.length?"Aramaya uyan not yok.":"Henüz not yok."}</p>`}
 <details class="v38-card"><summary><b>Haftalık plandaki notların</b> (${WN.length})</summary>${WN.length?`<ul class="v38-ul">${WN.map(w=>`<li><b>${esc(w.g)}. sınıf ${esc(w.py)} · ${esc(w.sy)} · takvimde ${esc(w.n)}. hafta</b><p class="v38-pre">${esc(w.x.text)}</p></li>`).join("")}</ul>`:`<p class="mut">Haftalık ekranda eklenmiş not yok.</p>`}</details></section>`};
V38.notSave=function(ev,id){ev.preventDefault();const f=ev.target,v=n=>f.elements[n].value.trim(),now=V38.now();if(!v("title")||!v("text"))return false;const L=V38.mem.notlar;
 if(id){const n=L.find(x=>x.id===id);if(n)Object.assign(n,{title:v("title"),text:v("text"),cls:v("cls"),taslak:f.elements.taslak.checked,updated:now})}else L.push({id:V38.uid("NT"),title:v("title"),text:v("text"),cls:v("cls"),taslak:f.elements.taslak.checked,created:now,updated:now});
 V38.put("notlar");V38.logT(id?"Not güncellendi":"Not eklendi",v("title"));V38.NS().ed="";UI.toast("Not kaydedildi.");OGRT.render();return false};
